    Let $G=(V,E)$ be a finite connected graph. Then we have
    \begin{equation}\label{11}
        1+\mu_{n-1}\geq \frac{(1-\mu_2)^2}{2h^2}
\left(\sqrt{1+\frac{h^2}{1-\mu_2}}-1\right)^2.
    \end{equation}

\label{26}
    Let $G$ be a finite, non-bipartite, vertex-transitive graph.
    There hold
\begin{equation}\label{22}
    1+\mu_n \geq {\rm min} \left\{\frac{2}{d}, \frac{(\sqrt{3}-1)^2}{8}h^2\right\},
\end{equation}
and
\begin{equation}\label{23}
    1+\mu_n \geq {\rm min} \left\{\frac{2}{d}, 2\left(\sqrt{1+\frac{1-\mu_2}{4}}-1\right)^2 \right \}.
\end{equation}

\label{1}
Let $G=(V,E)$ be a finite graph and $f$ be a function on $V$. We have
\begin{equation}
    \sum_{\{u,v\}\in E}(f(u)-f(v))^2=\  \langle f,(I-D^{-1}A)f\rangle
\end{equation}
and
\begin{equation}
    \sum_{\{u,v\}\in E}(f(u)+f(v))^2=\ \langle f,(I+D^{-1}A)f \rangle,
\end{equation}
where $I$ is the $n\times n$ identity matrix.

\label{4}
Let $G=(V,E)$ be a finite graph. For any nonzero function $f$ on $V$ satisfying
$\sum_{u \in V}f(u)d_u=0$, we have
\begin{equation}
    \frac{\sum_{\{u,v\}\in E}|f(u)-f(v)|}{\sum_{u \in V}|f(u)|d_u}\geq \frac{1}{2}h.
\end{equation}

Let $G=(V,E)$ be a finite graph. We have
\begin{equation}\label{18}
    2h \geq 1-\mu_2 \geq \frac{1}{2}h^2.
\end{equation}

\label{17}
Let $G=(V,E)$ be a finite graph and $f,g$ be two eigenfunctions of the eigenvalues $\mu$ and $\nu$ of the normalized adjacency matrix $D^{-1}A$, respectively.
We have the following estimate
\begin{equation*}
    \sum_{\{u,v\}\in E}|f(u)g(u)-f(v)g(v)|\leq \frac{\sqrt{2}}{2} \left(\sqrt{1+\mu}+\sqrt{1+\nu}\right)\Vert f\Vert_2\Vert g\Vert_2.
\end{equation*}
\begin{proof}
By Cauchy-Schwarz inequality and Lemma \ref{1}, we calculate
\begin{align*}
    & \sum_{\{u,v\}\in E}2|f(u)g(u)-f(v)g(v)|\\  = &\sum_{\{u,v\}\in E}|(f(u)-f(v))(g(u)+g(v))+(f(u)+f(v))(g(u)-g(v))|\\
    \leq & \sum_{\{u,v\}\in E}|(f(u)-f(v))(g(u)+g(v))|+\sum_{\{u,v\}\in E}|(f(u)+f(v))(g(u)-g(v))|\\
    \leq &\sqrt{\sum_{\{u,v\}\in E}(f(u)-f(v))^2}\sqrt{\sum_{\{u,v\}\in E}(g(u)+g(v))^2} \\
    &\hspace{3.5cm} +\sqrt{\sum_{\{u,v\}\in E}(f(u)+f(v))^2}\sqrt{\sum_{\{u,v\}\in E}(g(u)-g(v))^2}\\
    =& \left(\sqrt{(1-\mu)(1+\nu)}+\sqrt{(1+\mu)(1-\nu)}\right) \Vert f\Vert_2\Vert g\Vert_2 \\
    \leq & \sqrt{2} (\sqrt{1+\mu}+\sqrt{1+\nu})\Vert f\Vert_2\Vert g\Vert_2.
\end{align*}
This completes the proof.
\end{proof}

\label{3}
    Let $G=(V,E)$ be a finite connected graph. Assume that $f$ is an eigenfunction of the eigenvalue $\mu$ of the normalized adjacency matrix $D^{-1}A$ with $\Vert f\Vert_2=1$.
    Let  $\boldsymbol{c}$ is the constant function such that $\Vert c\Vert_2=1$ and $f_1:=|f|-\langle |f|,\boldsymbol{c}\rangle\boldsymbol{c}$. Then we have

\begin{equation*}
   \Vert f_1\Vert_2^2  \leq \frac{1+\mu}{1-\mu_2}
\end{equation*}
and
\begin{equation*}
    \langle |f|, \boldsymbol{c}\rangle^2 \geq 1-\frac{1+\mu}{1-\mu_2}.
\end{equation*}

Oberserving that $\langle f_1, \boldsymbol{c} \rangle=0$, we have $$(1-\mu_2) \langle f_1,f_1\rangle \leq \langle f_1,(I-D^{-1}A)f_1\rangle.$$
Therefore, we estimate by Lemma \ref{1}
\begin{equation*}
    \begin{split}
       \Vert f_1\Vert_2^2 &\leq \frac{1}{1-\mu_2}\langle f_1,(I-D^{-1}A)f_1\rangle= \frac{1}{1-\mu_2}\langle |f|,(I-D^{-1}A)|f|\rangle\\
       &= \frac{1}{1-\mu_2} \sum_{\{u,v\}\in E}(|f(u)|-|f(v)|)^2\\
       & \leq \frac{1}{1-\mu_2} \sum_{\{u,v\}\in E}(f(u)+f(v))^2\\
       & =\frac{1}{1-\mu_2} \langle f,(I+D^{-1}A)f \rangle\\
       & =\frac{1+\mu}{1-\mu_2}.
       \end{split}
\end{equation*}
The other inequality holds since $$1=\Vert f\Vert_2^2=\langle |f|,\boldsymbol{c}\rangle^2+\Vert f_1\Vert_2^2.$$
This concludes the proof.

\label{5}
    Let $G=(V,E)$ be a finite connected graph and $f,g$ be eigenfunctions of the eigenvalues $\mu$ and $\nu$ of $D^{-1}A$, respectively, such that  $\Vert f\Vert_2 =\Vert g\Vert_2=1$. Then
    \begin{equation}
        \langle |f|,|g|\rangle \geq \sqrt{1-\frac{1+\mu}{1-\mu_2}}\sqrt{1-\frac{1+\nu}{1-\mu_2}}-\sqrt{\frac{1+\mu}{1-\mu_2}}\sqrt{\frac{1+\nu}{1-\mu_2}}.
    \end{equation}
\begin{proof}
    Let  $\boldsymbol{c}$ be a positive constant function with $\Vert c\Vert_2=1$. Decompose $|f|$ and $|g|$ such that
$$|f|=\langle |f|,\boldsymbol{c}\rangle\boldsymbol{c}+f_1,\,\,\,\,\text{and}\,\,\,\,|g|=\langle |g|,\boldsymbol{c}\rangle\boldsymbol{c}+g_1.$$ Then we compute
\begin{equation*}
\begin{split}
    \langle |f|,|g|\rangle&=\langle |f|,\boldsymbol{c}\rangle\langle |g|,\boldsymbol{c}\rangle+\langle f_1,g_1\rangle\\
    &\geq \langle |f|,\boldsymbol{c}\rangle\langle |g|,\boldsymbol{c}\rangle-\Vert f_1\Vert_2\Vert g_1\Vert_2\\
    &\geq\sqrt{1-\frac{1+\mu}{1-\mu_2}}\sqrt{1-\frac{1+\nu}{1-\mu_2}}-\sqrt{\frac{1+\mu}{1-\mu_2}}\sqrt{\frac{1+\nu}{1-\mu_2}}
\end{split}
\end{equation*}
where the last inequality comes from Lemma \ref{3}.
\end{proof}

Let  $\boldsymbol{c}$ be a positive constant function with $\Vert c\Vert_2=1$. Decompose $|f|$ and $|g|$ such that
$$|f|=\langle |f|,\boldsymbol{c}\rangle\boldsymbol{c}+f_1,\,\,\,\,\text{and}\,\,\,\,|g|=\langle |g|,\boldsymbol{c}\rangle\boldsymbol{c}+g_1.$$ Then we compute
\begin{equation*}
\begin{split}
    \langle |f|,|g|\rangle&=\langle |f|,\boldsymbol{c}\rangle\langle |g|,\boldsymbol{c}\rangle+\langle f_1,g_1\rangle\\
    &\geq \langle |f|,\boldsymbol{c}\rangle\langle |g|,\boldsymbol{c}\rangle-\Vert f_1\Vert_2\Vert g_1\Vert_2\\
    &\geq\sqrt{1-\frac{1+\mu}{1-\mu_2}}\sqrt{1-\frac{1+\nu}{1-\mu_2}}-\sqrt{\frac{1+\mu}{1-\mu_2}}\sqrt{\frac{1+\nu}{1-\mu_2}}
\end{split}
\end{equation*}
where the last inequality comes from Lemma \ref{3}.

Let $f,g$ be eigenfunctions of the eigenvalues $\mu_n$ and $\mu_{n-1}$ such that $\Vert f\Vert_2=\Vert g\Vert_2=1$ and
    $\langle f, g\rangle=0$, i.e., $\sum_{u\in V}f(u)g(u)d_u=0$. Applying Proposition \ref{4} to the function $fg$ and inserting the estimates from Lemma \ref{17} and Lemma \ref{5}, we derive the following inequality
    $$
    \frac{\sqrt{2}}{2}h\leq \frac{ \sqrt{1+\mu_n}+\sqrt{1+\mu_{n-1}}}{\sqrt{1-\frac{1+\mu_n}{1-\mu_2}}\sqrt{1-\frac{1+\mu_{n-1}}{1-\mu_2}}-\sqrt{\frac{1+\mu_n}{1-\mu_2}}\sqrt{\frac{1+\mu_{n-1}}{1-\mu_2}}},
    $$
    when $1+\mu_{n-1} < (1-\mu_2)/2$.
    Notice that the following function
\begin{equation}
f(x,y)=\frac{\sqrt{x}+\sqrt{y}}{\sqrt{1-\frac{1}{1-\mu_2}x}\sqrt{1-\frac{1}{1-\mu_2}y}-\sqrt{\frac{1}{1-\mu_2}x}\sqrt{\frac{1}{1-\mu_2}y}}
\end{equation}
is continuous on $[0,\frac{1}{2}(1-\mu_2))\times[0,\frac{1}{2}(1-\mu_2))$, monotonically increasing with respect to either $x$ or $y$ and $f(0,0)=0$. Let $c=c(h,1-\mu_2)$ be the number such that $$f(c,c)=\frac{\sqrt{2}}{2}h.$$ Then we have $$1+\mu_{n-1}\geq c,$$ since, otherwise,
$$f(1+\mu_n,1+\mu_{n-1})< f(c,c)=\frac{\sqrt{2}}{2}h$$ is a contradiction. A direct computation shows that
\begin{equation*}
        \sqrt{c}=\frac{1-\mu_2}{\sqrt{2}h}
\left(\sqrt{1+\frac{h^2}{1-\mu_2}}-1\right).
\end{equation*}
This proves the inequality (\ref{11}) when $1+\mu_{n-1}<(1-\mu_2)/2$.

For the case that $1+\mu_{n-1} \geq (1-\mu_2)/2$, the inequality (\ref{11}) still holds since
$$1+\mu_{n-1} \geq \frac{1-\mu_2}{2}\geq \frac{(1-\mu_2)^2}{2h^2}
\left(\sqrt{1+\frac{h^2}{1-\mu_2}}-1\right)^2,$$
while the last inequality comes from the fact that $1-\mu_2 \geq 0$.

\label{15}
    Let $G=(V,E)$ be a finite graph. Let $n$, $\mu_2$, $\mu_{n-1}$ and  $h$ be as in Theorem \ref{1}. Then, we have
    \begin{equation}
        1+\mu_{n-1}\geq 2\left(\sqrt{1+\frac{1-\mu_2}{4}}-1\right)^2,
    \end{equation}

\begin{equation}\label{10}
        1+\mu_{n-1}\geq \frac{(\sqrt{3}-1)^2}{8}h^2.
\end{equation}

\label{thm:vertextransitive}
    Let $G$ be a finite connected vertex-transitive graph and $\mu$ a simple eigenvalue of its normalized adjacency matrix. Then
    \begin{equation}
    \mu=\frac{2k}{d}-1
    \end{equation}
    where $0\leq k \leq d$ is an integer and
    $d$ is the degree of $G$.

\label{16}
    Let $(G,S)$ be a finite connected Cayley graph with a finite group $G$ and a gernerating set $S$. Assume that $G$ is a simple group or the size $|G|$ is odd. Let $$-1< \mu_{n} \leq \mu_{n-1} \leq ... \leq \mu_{2} \leq \mu_{1}=1$$ be the eigenvalues of its normalized adjacency matrix where $n=|G|$. Denote by $h$ its edge-expansion. Then we have
\begin{equation}\label{7B}
    1+\mu_n \geq \frac{(\sqrt{3}-1)^2}{8}h^2
\end{equation}
and
\begin{equation}
        1+\mu_{n}\geq  2\left(\sqrt{1+\frac{1-\mu_2}{4}}-1\right)^2.
    \end{equation}
